@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,600;0,700;1,600;1,700&display=swap');
:root{--ink:#f7f3f5;--muted:#9893a3;--line:#343140;--bg:#171522;--panel:#201e2b;--pink:#f498bd;--coral:#ffb19b;--mint:#9ae3d5;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--serif:'Playfair Display',serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);min-height:100vh;background-image:radial-gradient(ellipse at 70% 8%,rgba(113,81,133,.13),transparent 40%)}button,input{font:inherit}button{color:inherit;cursor:pointer}.app-shell{max-width:1550px;margin:auto;padding:0 6.1%}.topbar{height:82px;border-bottom:1px solid rgba(255,255,255,.09);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;gap:12px;align-items:center;text-decoration:none;color:var(--ink);font-weight:700;font-size:13px;letter-spacing:2px}.brand i{font-style:normal;color:var(--pink);font-weight:400}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid #a87d99;border-radius:50%;font-family:serif;color:#f5acd0;font-size:19px;box-shadow:0 0 20px #ec84b42b}.season-tag,.eyebrow,.chapter span,.scene-caption b,.float-chip,.stage-footer,.stat small,.random-btn,.name-row label,.tab,.challenge small,.safety-copy,footer,.adult-note>span:first-child{font-family:var(--mono);letter-spacing:1.15px}.season-tag{font-size:10px;color:#c5bdcc;letter-spacing:1.6px}.season-tag b{color:#f193bc;margin:0 7px}.live-dot,.tiny-live{width:6px;height:6px;background:#a2e8cc;border-radius:50%;display:inline-block;margin-right:8px;box-shadow:0 0 11px #92e4c7}.top-actions{display:flex;gap:13px;align-items:center}.icon-btn{width:34px;height:34px;border:1px solid #393646;background:transparent;border-radius:50%;color:#bbb4c3;font-size:17px}.icon-btn:hover{color:white;border-color:#ef9cbd}.profile{display:flex;gap:9px;align-items:center;margin-left:12px;font-size:9px;letter-spacing:1.3px}.profile-avatar{width:34px;height:34px;background:#483345;color:#f6b4d2;display:grid;place-items:center;border-radius:50%;font-size:17px}.profile small{display:block;color:#a49baa;font:9px var(--mono);margin-top:4px}.profile small b{color:var(--pink)}.layout{display:grid;grid-template-columns:minmax(0,1.52fr) minmax(340px,.9fr);gap:34px;padding:27px 0 30px}.stage-heading{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:19px}.eyebrow{font-size:9px;color:#aaa2b2;letter-spacing:1.8px}.sparkle{color:#f3a5c4;margin-right:6px}h1{font-size:34px;line-height:1.05;margin:10px 0 2px;letter-spacing:-1.4px;font-weight:600}h1 em{font-family:var(--serif);font-weight:600;color:var(--pink)}.chapter{text-align:right;font-size:11px;padding-bottom:5px}.chapter span{font-size:8px;color:#8f8999;display:block;margin-bottom:6px}.chapter b{font-weight:500}.scene{height:572px;position:relative;overflow:hidden;border:1px solid #43374c;border-radius:4px;background:linear-gradient(180deg,#403454 0%,#6b425d 37%,#cb6a78 72%,#eea38e 100%);isolation:isolate;box-shadow:0 22px 60px #06050c66}.scene:before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(17,14,32,.25),transparent 32%,transparent 72%,rgba(19,15,30,.28));z-index:1;pointer-events:none}.scene-sun{position:absolute;width:270px;height:270px;border-radius:50%;left:44%;top:12%;background:radial-gradient(circle,#ffc0a0 0%,#fb9a9a 35%,#e880a133 65%,transparent 72%);opacity:.84}.scene-grid{position:absolute;bottom:-45px;left:-20%;right:-20%;height:230px;background:linear-gradient(180deg,transparent 0 5%,#f2a28f77 5.5%,transparent 6%,transparent 20%,#f6b19d55 20.5%,transparent 21%),repeating-linear-gradient(90deg,transparent 0 78px,#f3a39044 79px 81px);transform:perspective(220px) rotateX(48deg);transform-origin:top;z-index:0}.city{position:absolute;bottom:112px;display:flex;align-items:flex-end;gap:10px}.city i{display:block;width:60px;background:linear-gradient(90deg,#292139,#3d2c49 55%,#241c34);position:relative;box-shadow:inset 4px 0 #f39ab522}.city i:after{content:'';position:absolute;inset:14px 9px;background:repeating-linear-gradient(0deg,transparent 0 13px,#ffc88c99 14px 18px),repeating-linear-gradient(90deg,transparent 0 15px,#f8a6ac55 16px 21px)}.city-back{left:-10px;opacity:.72}.city-back i:nth-child(1){height:164px}.city-back i:nth-child(2){height:208px;width:78px}.city-back i:nth-child(3){height:146px}.city-back i:nth-child(4){height:188px;width:82px}.city-back i:nth-child(5){height:150px}.city-front{right:-15px;gap:6px;bottom:101px}.city-front i{width:72px;background:linear-gradient(90deg,#33233d,#50334b,#2b203b)}.city-front i:nth-child(1){height:175px}.city-front i:nth-child(2){height:222px}.city-front i:nth-child(3){height:159px}.city-front i:nth-child(4){height:203px}.city-front i:nth-child(5){height:166px}.sign{position:absolute;color:#ffb5bc;text-shadow:0 0 11px #fa7cb8,0 0 30px #f652a0;font-family:serif;z-index:1}.sign-one{right:11%;top:22%;font-size:26px;transform:rotate(4deg)}.sign-one small{font:8px var(--mono);display:block;text-align:center;letter-spacing:2px}.sign-two{left:7%;top:36%;font-size:12px;color:#fde2a7}.rain{position:absolute;inset:0;z-index:1;opacity:.32;background-image:repeating-linear-gradient(105deg,transparent 0 48px,#d8d3f26c 49px,#d8d3f26c 50px,transparent 51px 90px);background-size:120px 190px;animation:rain 1.1s linear infinite;mask-image:linear-gradient(transparent,#000 22%,#000)}@keyframes rain{to{background-position:0 190px}}.scene-vignette{position:absolute;inset:0;z-index:2;background:linear-gradient(0deg,rgba(22,16,34,.5),transparent 27%),radial-gradient(ellipse,transparent 45%,#22192c60 100%);pointer-events:none}.avatar-wrap{position:absolute;z-index:3;left:50%;bottom:10px;height:535px;width:350px;transform:translateX(-50%);filter:drop-shadow(0 14px 18px #24152d66);transition:transform .35s ease}.avatar-wrap.turn{transform:translateX(-50%) rotateY(180deg) scaleX(.95)}#avatar{height:100%;width:100%;overflow:visible;transform-origin:50% 70%;transition:filter .25s}.avatar-shadow{position:absolute;bottom:1px;left:25%;width:50%;height:16px;border-radius:50%;background:#281b385c;filter:blur(8px)}.scene-caption{position:absolute;z-index:5;left:20px;bottom:19px;display:flex;gap:10px;align-items:center}.caption-pin{font-size:22px;color:#ffc1bc}.scene-caption b{font-size:9px;letter-spacing:1.5px;display:block}.scene-caption small{font-size:10px;color:#d0c0ce;display:block;margin-top:5px}.float-chip{position:absolute;right:17px;top:17px;background:#282135a8;border:1px solid #ffffff3b;padding:9px 11px;border-radius:2px;font-size:8px;letter-spacing:1.1px;z-index:4}.weather-icon{color:#a7e4dc;font-size:13px;margin-right:7px}.stage-controls{position:absolute;bottom:19px;right:19px;display:flex;align-items:center;gap:9px;z-index:6}.round-control{border:1px solid #ffffff75;background:#1f1b2b88;width:36px;height:36px;border-radius:50%;font-size:19px;backdrop-filter:blur(8px)}.photo-button{height:38px;border:1px solid #f6a4c4;background:#e890b9;color:#241824;padding:0 17px;font:10px var(--mono);letter-spacing:1px;box-shadow:0 5px 16px #2c183955}.photo-button span{font-size:19px;vertical-align:-2px;margin-right:6px}.stage-footer{z-index:5;position:absolute;top:17px;left:17px;right:17px;display:flex;justify-content:space-between;font-size:8px;color:#f7d8e0;letter-spacing:1.2px}.stage-footer b{color:#ffc1cf}.event-toast{position:absolute;top:64px;left:50%;transform:translate(-50%,-10px);background:#201c2de8;border:1px solid #e6a3c4;padding:10px 17px;font-size:11px;z-index:8;opacity:0;transition:.3s;white-space:nowrap;pointer-events:none}.event-toast.show{opacity:1;transform:translate(-50%,0)}.toast-icon{color:#f3a2c2;margin-right:9px}.bottom-stats{display:flex;align-items:center;gap:25px;padding:17px 4px 0}.stat-label{margin-right:auto}.stat-label .eyebrow{display:block;font-size:8px}.stat-label>b{font-size:11px;font-weight:500;display:block;margin-top:6px;color:#d9d4df}.stat{display:flex;align-items:center;gap:8px}.stat-icon{font-size:22px;color:#f39bbc}.stat-icon.heart{font-size:27px}.stat b{font-size:15px;display:block;font-weight:500}.stat small,.stat-score small{display:block;color:#938c9c;font-size:8px;margin-top:2px}.stat-score{text-align:right;border-left:1px solid var(--line);padding-left:20px;color:var(--mint)}.stat-score span{font:17px var(--mono)}.creator-panel{background:linear-gradient(150deg,#24212f,#1d1b27);border:1px solid #353140;padding:21px 22px 17px;min-height:720px;display:flex;flex-direction:column;box-shadow:0 16px 45px #09081033}.panel-top{display:flex;justify-content:space-between;align-items:center}.panel-top h2{margin:7px 0 0;font:25px var(--serif);letter-spacing:-.3px}.tiny-spark{color:var(--pink);font-size:12px}.random-btn{background:transparent;border:1px solid #484252;color:#d4ced9;height:31px;padding:0 10px;font-size:15px}.random-btn span{font-size:8px;vertical-align:2px;margin-left:3px}.adult-note{display:flex;gap:10px;align-items:center;background:#2c2632;border:1px solid #483442;padding:8px 10px;margin:17px 0 15px;color:#b8adbc;font-size:9px;line-height:1.55}.adult-note>span:first-child{display:grid;place-items:center;border:1px solid #f1a2c3;color:#f3a5c5;border-radius:50%;width:27px;height:27px;flex-shrink:0;font-size:9px}.name-row{display:flex;justify-content:space-between;align-items:center;margin-bottom:13px}.name-row label{color:#9e96a6;font-size:8px}.name-input-wrap{display:flex;align-items:center;border-bottom:1px solid #574c5b;width:53%;color:#baadbb}.name-input-wrap input{background:transparent;border:0;outline:0;color:#fff;width:100%;font:13px var(--serif);padding:4px 0}.name-input-wrap span{font-size:13px}.tabs{display:grid;grid-template-columns:repeat(3,1fr);border-bottom:1px solid #373340}.tab{border:0;background:transparent;color:#938c9b;padding:12px 0 10px;font-size:9px;letter-spacing:1.3px;position:relative}.tab.active{color:#f2a4c4}.tab.active:after{content:'';height:2px;position:absolute;bottom:-1px;left:0;right:0;background:#f2a4c4}.tab-content{padding-top:15px;flex:1;min-height:245px}.group{margin-bottom:16px}.group-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px}.group-heading label{font:9px var(--mono);letter-spacing:1.1px;color:#c6becb}.group-heading small{font:8px var(--mono);color:#867e8d}.options{display:flex;gap:7px;flex-wrap:wrap}.choice{position:relative;border:1px solid #474151;background:#282532;color:#d1cbd4;font-size:10px;padding:8px 10px;min-height:32px;transition:.2s}.choice:hover{border-color:#b07e9b}.choice.selected{border-color:#ed9cbe;background:#412d40;color:#ffd2e4;box-shadow:inset 0 0 0 1px #ed9cbe33}.color-choice{width:32px;height:32px;padding:3px;border-radius:50%;background:#282532}.color-choice i{display:block;width:100%;height:100%;border-radius:50%;border:1px solid #ffffff4a}.color-choice.selected{box-shadow:0 0 0 1px #201e2b,0 0 0 2px #f1a2c1}.mini-card{width:calc(33.33% - 5px);height:68px;border:1px solid #423d4a;background:linear-gradient(140deg,#342b3c,#24212d);display:flex;flex-direction:column;justify-content:flex-end;align-items:flex-start;padding:8px;color:#e3dce6;text-align:left;font-size:9px;position:relative}.mini-card:before{content:attr(data-icon);position:absolute;top:6px;right:8px;color:#ee9fc1;font-size:19px}.mini-card.selected{border-color:#e99bbc;background:linear-gradient(140deg,#49334a,#292331)}.panel-bottom{margin-top:auto}.challenge{display:flex;align-items:center;gap:11px;border:1px solid #3c3744;background:#26232f;padding:10px 12px;margin:12px 0}.challenge-icon{color:#f1a3c4;font-size:21px}.challenge small{font-size:7px;color:#a59cab;display:block}.challenge b{font-size:10px;font-weight:500;display:block;margin-top:3px}.challenge-arrow{margin-left:auto;color:#b5a7b5;font-size:17px}.primary-btn{width:100%;height:44px;background:linear-gradient(100deg,#ef9cbd,#f4b39b);color:#271c2a;border:0;font:10px var(--mono);letter-spacing:1.2px;text-align:left;padding:0 14px;box-shadow:0 6px 19px #e990b21a}.primary-btn span{margin-right:9px}.primary-btn i{float:right;font-style:normal;font-size:17px;line-height:10px}.primary-btn:hover,.photo-button:hover{filter:brightness(1.08);transform:translateY(-1px)}.safety-copy{text-align:center;color:#8e8796;font-size:7px;letter-spacing:.3px;line-height:1.7;margin-top:10px}footer{display:flex;justify-content:space-between;padding:15px 0 23px;border-top:1px solid #302d39;color:#8b8492;font-size:8px;letter-spacing:1.2px}footer b{font-weight:400;color:#5e5965}footer i{color:#ee9fbe;font-style:normal}.toast{position:fixed;bottom:22px;left:50%;transform:translate(-50%,15px);background:#282432;border:1px solid #785269;color:#f6d5e4;padding:11px 20px;font-size:12px;z-index:20;opacity:0;transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.mood-card{width:calc(50% - 4px);border:1px solid #423d4a;background:#292632;padding:11px;text-align:left;color:#ded6e0}.mood-card b{font-size:10px;font-weight:500;display:block}.mood-card small{font:8px var(--mono);color:#9c94a3;display:block;margin-top:5px}.mood-card.selected{border-color:#e99bbc;color:#ffd0e1;background:#3b2b3c}
@media(min-width:1450px){.scene{height:620px}.avatar-wrap{height:575px}.layout{grid-template-columns:minmax(0,1.5fr) minmax(370px,.86fr)}}
@media(max-width:1050px){.app-shell{padding:0 3%}.layout{gap:20px;grid-template-columns:minmax(0,1.2fr) minmax(330px,.9fr)}.scene{height:530px}.avatar-wrap{height:490px}.creator-panel{padding:18px}.season-tag{display:none}}
@media(max-width:760px){.app-shell{padding:0 14px}.topbar{height:64px}.brand{font-size:11px}.profile{display:none}.top-actions{gap:7px}.layout{display:flex;flex-direction:column;gap:20px;padding-top:19px}.stage-heading{margin-bottom:14px}.stage-heading h1{font-size:29px}.chapter{font-size:10px}.scene{height:min(550px,118vw);min-height:390px}.avatar-wrap{height:90%;width:65%;bottom:7px}.scene-caption{bottom:14px;left:12px}.stage-controls{bottom:12px;right:12px;gap:6px}.round-control{width:32px;height:32px}.photo-button{height:34px;padding:0 10px;font-size:8px}.float-chip{right:10px;top:38px}.stage-footer{top:12px;left:12px;right:12px}.bottom-stats{gap:15px;padding:13px 0 0}.stat-label>b{max-width:130px;font-size:9px}.stat-score{padding-left:10px}.stat b{font-size:13px}.creator-panel{min-height:650px;padding:17px}.tab-content{min-height:235px}.panel-bottom{margin-top:8px}footer{font-size:7px}.city{bottom:90px}}
@media(max-width:390px){.app-shell{padding:0 10px}.scene{min-height:360px}.bottom-stats{gap:9px}.stat-label>b{display:none}.stat-score{padding-left:8px}.stat-score span{font-size:14px}.creator-panel{padding:14px}.adult-note{font-size:8px}.scene-caption b{font-size:8px}.scene-caption small{font-size:9px}}

const state={name:'Akari',hair:'Midnight',hairColor:'#28213c',eye:'#9be3d3',outfit:'Starlight',outfitColor:'#b74f83',accessory:'Moon clips',pose:0,scene:0,moment:0,tab:'look',likes:128,rep:340,shoots:0,angle:0};
const hairChoices=[['Midnight','#28213c'],['Rose gold','#d88782'],['Silver','#d5d4e4'],['Teal','#438a88'],['Violet','#79569d']];
const eyeChoices=[['Jade','#9be3d3'],['Amethyst','#b899ef'],['Honey','#edbd73'],['Ocean','#7ac8e9']];
const outfitChoices=[['Starlight','#b74f83'],['City chic','#364b68'],['Moonlit','#71699e'],['Cherry pop','#ad554c'],['Mint dream','#4b887c']];
const accessories=['Moon clips','Star beret','Ribbon bow','No accessory'];
const outfits=[['Starlight','✧'],['City chic','◈'],['Moonlit','☾'],['Cherry pop','❀'],['Mint dream','✦']];
const scenes=[{name:'SHIBUYA · 23:17',mood:'Neonregen, leere Straßen',weather:'REGEN-SPECIAL',bg:'linear-gradient(180deg,#403454 0%,#6b425d 37%,#cb6a78 72%,#eea38e 100%)'}, {name:'ROOFTOP · 20:42',mood:'Golden hour über der Stadt',weather:'GOLDEN HOUR',bg:'linear-gradient(180deg,#423653 0%,#a75d77 45%,#f2a676 83%,#eac19a 100%)'}, {name:'ART DISTRICT · 21:06',mood:'Galerielicht und große Träume',weather:'NIGHT BLOOM',bg:'linear-gradient(180deg,#282d49 0%,#514164 45%,#95707d 83%,#d18b83 100%)'}];
const moments=[['Regen überrascht dich','Ein Windstoß klaut den Schirm.','☂'],['Kaffee-Katastrophe','Ein Tropfen auf dem Mantel — oh nein!','☕'],['Spotlight!','Alle Augen auf deinen dramatischen Auftritt.','✦'],['Falsche Pose?','Die Kamera erwischt dein verlegenes Lächeln.','◎']];
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
function setTab(tab){state.tab=tab;$$('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===tab));renderTab()}
function choice(label,selected,action,klass=''){return `<button class="choice ${klass} ${selected?'selected':''}" data-action="${action}" data-value="${label}">${label}</button>`}
function colorChoices(list,current,action){return `<div class="options">${list.map(([name,color])=>`<button class="choice color-choice ${current===color?'selected':''}" data-action="${action}" data-value="${color}" title="${name}" aria-label="${name}"><i style="background:${color}"></i></button>`).join('')}</div>`}
function cardOptions(list,current,action){return `<div class="options">${list.map(([name,icon])=>`<button class="mini-card ${current===name?'selected':''}" data-action="${action}" data-value="${name}" data-icon="${icon}">${name}</button>`).join('')}</div>`}
function renderTab(){const target=$('#tabContent'); if(state.tab==='look'){target.innerHTML=`<div class="group"><div class="group-heading"><label>HAARFARBE</label><small>01 / 04</small></div>${colorChoices(hairChoices,state.hairColor,'hair')}</div><div class="group"><div class="group-heading"><label>AUGENFARBE</label><small>02 / 04</small></div>${colorChoices(eyeChoices,state.eye,'eye')}</div><div class="group"><div class="group-heading"><label>FRISUR</label><small>03 / 04</small></div><div class="options">${choice('Soft waves',state.pose%3===0,'hairStyle')} ${choice('Twin tails',state.pose%3===1,'hairStyle')} ${choice('Long & sleek',state.pose%3===2,'hairStyle')}</div></div><div class="group"><div class="group-heading"><label>ACCESSOIRE</label><small>04 / 04</small></div><div class="options">${accessories.map(x=>choice(x,state.accessory===x,'accessory')).join('')}</div></div>`}else if(state.tab==='style'){target.innerHTML=`<div class="group"><div class="group-heading"><label>OUTFIT · FULL COVERAGE</label><small>01 / 02</small></div>${cardOptions(outfits,state.outfit,'outfit')}</div><div class="group"><div class="group-heading"><label>FARBAKZENT</label><small>02 / 02</small></div>${colorChoices(outfitChoices,state.outfitColor,'outfitColor')}</div><div class="group"><div class="group-heading"><label>POSE</label><small>FINISHING TOUCH</small></div><div class="options">${['Confident','Shy smile','One hand wave'].map((x,i)=>choice(x,state.pose===i,'poseSet')).join('')}</div></div>`}else{target.innerHTML=`<div class="group"><div class="group-heading"><label>DEIN HINTERGRUND</label><small>01 / 02</small></div><div class="options">${[['Shibuya','▥'],['Rooftop','☼'],['Art district','◇']].map(([x,ic],i)=>`<button class="mini-card ${state.scene===i?'selected':''}" data-action="scene" data-value="${i}" data-icon="${ic}">${x}</button>`).join('')}</div></div><div class="group"><div class="group-heading"><label>AWKWARD MOMENT · FULLY CLOTHED</label><small>02 / 02</small></div><div class="options">${moments.map(([x,desc,icon],i)=>`<button class="mood-card ${state.moment===i?'selected':''}" data-action="moment" data-value="${i}"><b><span style="color:var(--pink);margin-right:5px">${icon}</span>${x}</b><small>${desc}</small></button>`).join('')}</div></div>`}
 target.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>act(el.dataset.action,el.dataset.value)));}
